// RFQ delivery requirements are requests, never delivery commitments.
const rfqProvinces=['Eastern Cape','Free State','Gauteng','KwaZulu-Natal','Limpopo','Mpumalanga','North West','Northern Cape','Western Cape'];
function rfqSiteCount(value){const count=Number(value);return Number.isInteger(count)&&count>=1&&count<=50?count:0}
function rfqAddressField(name,label,value='',required=false,type='text',extra=''){return `<div class="field"><label for="${name}">${label}${required?' *':''}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" maxlength="250" ${required?'required':''} ${extra}></div>`}
function rfqProvinceField(id,value='',extra=''){return `<div class="field"><label for="${id}">Province *</label><select id="${id}" ${extra||`name="${id}"`} required><option value="">Select a province</option>${rfqProvinces.map(p=>`<option ${value===p?'selected':''}>${p}</option>`).join('')}</select></div>`}
function rfqAdditionalSiteFields(){const count=rfqSiteCount(formData.sites);if(count<2)return '';return `<p class="help">The main delivery contact applies to each site unless you provide both a site contact and phone number.</p>${Array.from({length:count-1},(_,i)=>{const site=formData.deliveryLocations?.[i]||{},field=(key,label,required=false,type='text',extra='')=>rfqAddressField('delivery-site-'+i+'-'+key,label,site[key],required,type,`data-delivery-site="${i}" data-delivery-key="${key}" ${extra}`);return `<fieldset class="rfq-location"><legend>Delivery location ${i+2}</legend><div class="fields">${field('label','Site / branch name')}${field('street','Street number and name',true)}${field('building','Building / unit / floor')}${field('suburb','Suburb',true)}${field('town','Town / city',true)}${rfqProvinceField('delivery-site-'+i+'-province',site.province,`data-delivery-site="${i}" data-delivery-key="province"`)}${field('postcode','Postal code',true,'text','pattern="[0-9]{4}" inputmode="numeric" title="Four-digit South African postal code"')}${field('contact','Site contact (if different)')}${field('phone','Site phone (if different)','', 'tel')}${field('instructions','Delivery instructions')}</div><p class="delivery-area-alert" data-delivery-alert="${i}" role="status"></p></fieldset>`}).join('')}`}
function rfqDeliveryStep(){const b=formData,same=b.deliveryContactSame!=='no';return `<fieldset class="form-section rfq-delivery"><legend>Delivery requirements</legend><p class="help">Provide physical delivery addresses. Availability, charges and delivery timing will be confirmed in your quotation.</p><fieldset class="rfq-location"><legend>Main delivery location</legend><div class="fields">${rfqAddressField('deliveryStreet','Street number and name',b.deliveryStreet,true)}${rfqAddressField('deliveryBuilding','Building / unit / floor',b.deliveryBuilding)}${rfqAddressField('deliverySuburb','Suburb',b.deliverySuburb,true)}${rfqAddressField('town','Town / city',b.town,true)}${rfqProvinceField('province',b.province)}${rfqAddressField('postcode','Postal code',b.postcode,true,'text','pattern="[0-9]{4}" inputmode="numeric" title="Four-digit South African postal code"')}${rfqAddressField('deliveryInstructions','Delivery instructions',b.deliveryInstructions)}</div><p class="delivery-area-alert" id="delivery-area-alert" role="status"></p></fieldset><fieldset class="rfq-location"><legend>Delivery contact</legend><label class="rfq-contact-choice"><input id="delivery-same-contact" type="checkbox" ${same?'checked':''}>Use enquiry contact for delivery</label><div class="fields">${rfqAddressField('deliveryContact','Contact name',same?b.contact:b.deliveryContact,true)}${rfqAddressField('deliveryPhone','Contact telephone',same?(b.phone||b.deliveryPhone):b.deliveryPhone,true,'tel')}</div><p class="help" id="delivery-phone-help">If no telephone was supplied with your enquiry, enter a delivery contact number here.</p></fieldset><div class="fields rfq-delivery-count">${rfqAddressField('sites','Number of delivery locations',b.sites||'1',true,'number','min="1" max="50" step="1"')}</div><p class="help">For more than one location, complete the additional addresses below. For more than 50 locations, contact Lepetse to arrange a distribution schedule.</p><div id="rfq-additional-locations">${rfqAdditionalSiteFields()}</div><fieldset class="rfq-location"><legend>Requested timing</legend><div class="fields">${input('date','Requested delivery date','date')}${input('timing','Date flexibility','select',true,'Required on this date|Flexible, please discuss')}</div><p class="help">This is your requested date, subject to confirmation in the quotation.</p><p class="delivery-area-alert" id="delivery-date-alert" role="status"></p></fieldset>${b.buyerType==='Government / public entity'?`<fieldset class="rfq-location"><legend>Formal RFQ details</legend><div class="fields">${input('reference','RFQ / tender reference')}${input('deadline','Closing date and time SAST','datetime-local')}${input('channel','Official submission channel')}${input('briefing','Mandatory briefing','select',true,'No|Yes, see RFQ documents|To be confirmed')}</div><p class="help">Attach the original RFQ on the previous step. Include addenda and briefing details in your notes.</p></fieldset>`:''}</fieldset>`}
function captureRfqDelivery(){if(!$('#deliveryStreet'))return;formData.deliveryContactSame=$('#delivery-same-contact').checked?'yes':'no';if(formData.deliveryContactSame==='yes'){formData.deliveryContact=formData.contact||'';if(formData.phone)formData.deliveryPhone=formData.phone}const count=rfqSiteCount(formData.sites);if(count)formData.deliveryLocations=Array.from({length:count-1},(_,i)=>{const fields=[...document.querySelectorAll(`[data-delivery-site="${i}"]`)];return fields.length?Object.fromEntries(fields.map(e=>[e.dataset.deliveryKey,e.value.trim()])):formData.deliveryLocations?.[i]||{}});for(const key of Object.keys(formData))if(key.startsWith('delivery-site-'))delete formData[key]}
function rfqAreaWarning(town,province){return /^(johannesburg|pretoria)$/i.test((town||'').trim())&&province&&province!=='Gauteng'?`Check the province: ${/^pretoria$/i.test((town||'').trim())?'Pretoria':'Johannesburg'} is in Gauteng. Confirm the delivery location before continuing.`:''}
function rfqShortNotice(date){const today=new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'}),days=(Date.parse(date+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000;return Number.isFinite(days)&&days>=0&&days<=2?'Short-notice request. Availability and delivery on this date must be confirmed.':''}
function updateRfqDeliveryAlerts(){if(!$('#deliveryStreet'))return;$('#delivery-area-alert').textContent=rfqAreaWarning($('#town').value,$('#province').value);$('#delivery-date-alert').textContent=rfqShortNotice($('#date').value);document.querySelectorAll('[data-delivery-alert]').forEach(e=>{const i=e.dataset.deliveryAlert;e.textContent=rfqAreaWarning($('#delivery-site-'+i+'-town')?.value,$('#delivery-site-'+i+'-province')?.value)})}
function syncRfqDeliveryContact(){const same=$('#delivery-same-contact').checked;$('#deliveryContact').readOnly=same;$('#deliveryPhone').readOnly=same&&!!formData.phone;if(same){$('#deliveryContact').value=formData.contact||'';if(formData.phone)$('#deliveryPhone').value=formData.phone}}
function bindRfqDelivery(){if(!$('#deliveryStreet'))return;syncRfqDeliveryContact();updateRfqDeliveryAlerts();$('#delivery-same-contact').onchange=()=>{capture();syncRfqDeliveryContact()};$('#sites').oninput=()=>{capture();$('#rfq-additional-locations').innerHTML=rfqAdditionalSiteFields();updateRfqDeliveryAlerts()};$('#rfq').addEventListener('input',updateRfqDeliveryAlerts)}
function validateRfqDelivery(){if(!$('#deliveryStreet'))return '';if(!rfqSiteCount(formData.sites))return 'Enter a whole number of delivery locations from 1 to 50.';for(const [i,site]of (formData.deliveryLocations||[]).entries()){if(!site.street||!site.suburb||!site.town||!rfqProvinces.includes(site.province)||!/^\d{4}$/.test(site.postcode||''))return `Complete the physical address for delivery location ${i+2}.`;if(!!site.contact!==!!site.phone)return `Enter both a contact name and phone number for delivery location ${i+2}, or leave both blank to use the main contact.`}return ''}
function rfqDeliveryLocations(b){if(!b.deliveryStreet)return [];const main={street:b.deliveryStreet,building:b.deliveryBuilding,suburb:b.deliverySuburb,town:b.town,province:b.province,postcode:b.postcode,contact:b.deliveryContact,phone:b.deliveryPhone,instructions:b.deliveryInstructions};return [main,...(b.deliveryLocations||[]).slice(0,Math.max(0,rfqSiteCount(b.sites)-1)).map(x=>({...x,contact:x.contact||main.contact,phone:x.phone||main.phone}))]}
function rfqDeliveryReview(b){const locations=rfqDeliveryLocations(b);return `<div class="rfq-review-locations">${locations.map((x,i)=>`<section class="rfq-review-location"><h4>${locations.length>1?'Delivery location '+(i+1):'Delivery address'}${x.label?' · '+esc(x.label):''}</h4>${reviewFacts([['Street address',[x.building,x.street].filter(Boolean).join(', ')],['Suburb',x.suburb],['Town / city',x.town],['Province',x.province],['Postal code',x.postcode],['Delivery contact',[x.contact,x.phone].filter(Boolean).join(' · ')]])}${x.instructions?`<p><strong>Delivery instructions:</strong> ${esc(x.instructions)}</p>`:''}${rfqAreaWarning(x.town,x.province)?`<p class="delivery-area-alert">${rfqAreaWarning(x.town,x.province)}</p>`:''}</section>`).join('')}</div>${reviewFacts([['Delivery locations',`${locations.length} location${locations.length===1?'':'s'}`],['Requested delivery',reviewDate(b.date)],['Flexibility',b.timing==='Required on this date'?'Fixed date':'Flexible']])}<p class="help">Availability, delivery charges and timing will be confirmed in your quotation.</p>${rfqShortNotice(b.date)?`<p class="delivery-area-alert">${rfqShortNotice(b.date)}</p>`:''}`}
function rfqDeliveryDocument(b){const locations=rfqDeliveryLocations(b);if(!locations.length)return '';return `<section><h2>Delivery addresses and contacts</h2>${locations.map((x,i)=>`<h3>Delivery location ${i+1}${x.label?' · '+esc(x.label):''}</h3><dl>${[['Street address',[x.building,x.street].filter(Boolean).join(', ')],['Suburb',x.suburb],['Town / city',x.town],['Province',x.province],['Postal code',x.postcode],['Delivery contact',x.contact],['Telephone',x.phone],['Delivery instructions',x.instructions]].filter(([,v])=>v).map(([l,v])=>`<div><dt>${l}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`).join('')}<p>Requested delivery: ${esc(reviewDate(b.date))}. Availability, charges and timing require confirmation in the quotation.</p></section>`}
function rfqDeliveryEmail(b){return rfqDeliveryLocations(b).flatMap((x,i)=>[`Delivery location ${i+1}${x.label?' — '+x.label:''}`,[x.building,x.street,x.suburb,x.town,x.province,x.postcode].filter(Boolean).join(', '),`Delivery contact: ${x.contact||''} · ${x.phone||''}`,`Delivery instructions: ${x.instructions||''}`])}

function rfqCompactDocument(b){const locations=rfqDeliveryLocations(b),line=(label,value)=>value?`<p><strong>${label}:</strong> ${esc(value)}</p>`:'';return `<div class="rfq-document-overview"><section><h2>Buyer and contact</h2><p class="compact-primary">${esc(b.organisation)}</p><p>${[b.buyerType,b.orderType].filter(Boolean).map(esc).join(' · ')}</p><p>${[b.contact,b.email,b.phone].filter(Boolean).map(esc).join(' · ')}</p>${line('Previous order / quote',b.previousReference)}${line('Purchase-order reference',b.poNumber)}${line('Cost centre / department',b.costCentre)}${line('Grade / class',b.grade)}${line('Learners / packs',b.learners)}${line('Quantity basis',b.quantityBasis)}${line('Packing requested',b.packing)}${line('Labelling instructions',b.labelling)}</section><section><h2>Delivery · ${locations.length} location${locations.length===1?'':'s'}</h2>${locations.map((x,i)=>`<div class="compact-delivery-location">${locations.length>1?`<h3>Location ${i+1}${x.label?' · '+esc(x.label):''}</h3>`:''}<p class="compact-primary">${esc([x.building,x.street].filter(Boolean).join(', '))}</p><p>${[x.suburb,x.town,x.province,x.postcode].filter(Boolean).map(esc).join(', ')}</p>${line('Contact',x.contact===b.contact&&x.phone===b.phone?'Same as buyer':[x.contact,x.phone].filter(Boolean).join(' · '))}${line('Instructions',x.instructions)}${rfqAreaWarning(x.town,x.province)?`<p class="compact-warning">${esc(rfqAreaWarning(x.town,x.province))}</p>`:''}</div>`).join('')}${line('Requested date',[reviewDate(b.date),b.timing==='Required on this date'?'Fixed date':'Flexible'].filter(Boolean).join(' · '))}<p class="compact-note">Delivery availability, charges and timing require confirmation in the quotation.</p></section></div>${scheduleSummary(b)}${b.reference||b.deadline||b.channel||b.briefing?`<section><h2>Formal RFQ details</h2>${line('RFQ reference',b.reference)}${line('Closing deadline',b.deadline?b.deadline.replace('T',' ')+' SAST':'')}${line('Submission channel',b.channel)}${line('Mandatory briefing',b.briefing)}</section>`:''}`}
